readingTexts.forEach((text,i)=>{const s=readingStudy[text.id||'base-'+i];if(!s)return;text.vocab=s.v;text.questions=s.q.map(([qe,qs,opts,a,we,ws])=>{sentenceTranslations[qe]=qs;opts.forEach(([oe,os])=>{sentenceTranslations[oe]=os});return [qe,opts.map(o=>o[0]),a,ws,we]})});
